//! 🔤️ Actual UTF8 copy completion owns the only transferable output across every cancellation cut.
use super::*;
use semio_framework_test_fixtures::fixture_text;
use crate::observe_retirement_allocations as observe;
fn grant(d:crate::RetirementDemand,body:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body.max(d.copy_bytes),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]
fn string_clone_output_waits_for_complete_owned_payload_and_closes_each_cut(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../../🧬️retained-clone/🧬️contract/🔤️string-cursor/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in law["closeGrants"].as_array().unwrap(){let d=&row["demand"];let g=&row["grant"];let demand=crate::RetirementDemand{copy_bytes:d["copyBytes"].as_u64().unwrap()as usize,capacity_bytes:d["capacityBytes"].as_u64().unwrap()as usize,release_bytes:d["releaseBytes"].as_u64().unwrap()as usize,depth:d["depth"].as_u64().unwrap()as usize};let issued=RetainedCloneGrant{maximum_items:g["items"].as_u64().unwrap()as usize,maximum_copy_bytes:g["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["depth"].as_u64().unwrap()as usize};assert_eq!(retained_clone_grant_admits(issued,demand),row["accepted"].as_bool().unwrap());}
 for row in law["texts"].as_array().unwrap(){let text=row["text"].as_str().unwrap().repeat(row["repeat"].as_u64().unwrap()as usize);for body in law["bodyBytes"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;for cut in law["cancelCuts"].as_array().unwrap(){for close_first in law["closeBeforeTake"].as_array().unwrap(){
  let payload=text.clone();let birth=RetainedCloneSource::<String>::owned_constructor_demand::<()>();let issued=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:RetainedCloneSource::<String>::constructor_copy_bytes(),maximum_capacity_bytes:birth.capacity_bytes,maximum_depth:birth.depth,..Default::default()};let(result,heap)=observe(||RetainedCloneSource::admit_owned(payload,(),issued));let(mut source,receipt)=result.map_err(|(error,..)|error).unwrap();assert!(receipt.fits(issued));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));let original=source.borrow().get().as_ptr();let mut cursor=String::retained_clone_cursor();assert!(!cursor.output_ready());assert!(cursor.take().is_none());let mut complete=false;let mut turns=0;let maximum=text.len().checked_mul(8).and_then(|n|n.checked_add(1024)).unwrap();
  while !complete&&cut.as_u64().is_none_or(|cut|turns<cut as usize){let d=cursor.advance_demands(source.borrow(),body).unwrap();let issued=grant(d,body);let(step,heap)=observe(||cursor.advance(source.borrow(),body,issued).unwrap());assert!(step.progress().fits(issued));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));complete=matches!(step,RetainedCloneStep::Complete(_));assert_eq!(cursor.output_ready(),complete,"partial reservation/copy cannot transfer the original string output");if !complete{assert!(cursor.take().is_none());}assert_eq!(source.borrow().get().as_ptr(),original);turns+=1;assert!(turns<maximum);}
  if complete&&!close_first.as_bool().unwrap(){let(output,heap)=observe(||cursor.take());assert_eq!(heap,(0,0));assert_eq!(output.as_deref(),Some(text.as_str()));assert!(!cursor.output_ready());assert!(cursor.take().is_none());}
  cursor.begin_close();assert!(!cursor.output_ready());assert!(cursor.take().is_none());let(mut close_turns,mut close_idle)=(0,0);while !cursor.terminal_is_empty(){let d=cursor.close_demands(4096).unwrap();let issued=grant(d,0);let(step,heap)=observe(||cursor.close_step(issued).unwrap());assert!(step.progress().fits(issued));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));let unchanged=step.progress()==Default::default()&&!cursor.terminal_is_empty()&&cursor.close_demands(4096).unwrap()==d;close_idle=if unchanged{close_idle+1}else{0};assert!(close_idle<law["maximumIdleTurns"].as_u64().unwrap()as usize,"String close underquoted its actual selected transition: {d:?}");close_turns+=1;assert!(close_turns<law["closeTurns"].as_u64().unwrap()as usize);}assert_eq!(observe(||drop(cursor)).1,(0,0));let(mut source_turns,mut idle)=(0,0);while !source.terminal_is_empty(){let d=source.next_close_demand(4096).unwrap();assert!(d.copy_bytes<=4096);let issued=grant(d,4096);let(step,heap)=observe(||source.close_step(issued).unwrap());assert!(step.progress().fits(issued));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));let unchanged=step.progress()==Default::default()&&!source.terminal_is_empty()&&source.next_close_demand(4096).unwrap()==d;idle=if unchanged{idle+1}else{0};source_turns+=1;assert!(idle<law["maximumIdleTurns"].as_u64().unwrap()as usize,"source repeated an unchanged receipt and quote: {d:?}, len={}, cut={cut}",text.len());assert!(source_turns<law["closeTurns"].as_u64().unwrap()as usize,"source exceeded constant String Bytes/frame closure work: {d:?}, len={}, cut={cut}",text.len());}assert_eq!(observe(||drop(source)).1,(0,0));
 }}}}
}
